export type ApiErrorCode = "already_undone" | "in_use" | "idempotency_conflict" | "not_found" | "claim_conflict" | "stale_claim" | "validation" | "archived" | "conflict" | "not_ready" | "execution_required" | "wrong_status" | "forbidden" | "internal";

